const messages = $('messages').item.json.messages || '';
const id = $('messages').item.json.id || '';
let image_base64 = null;
let image_media_type = null;
let document_base64 = null;
let document_media_type = null;
try {
  const raw = $('Redis Get Image').item.json.image_data;
  if (raw) {
    const parsed = JSON.parse(raw);
    image_base64 = parsed.image_base64 || null;
    image_media_type = parsed.image_media_type || null;
  }
} catch (e) {}
try {
  const raw = $('Redis Get Document').item.json.document_data;
  if (raw) {
    const parsed = JSON.parse(raw);
    document_base64 = parsed.document_base64 || null;
    document_media_type = parsed.document_media_type || null;
  }
} catch (e) {}
const body = { message: messages, contactId: id };
if (image_base64) { body.image_base64 = image_base64; body.image_media_type = image_media_type; }
if (document_base64) { body.document_base64 = document_base64; body.document_media_type = document_media_type; }
const bodyJson = JSON.stringify(body);
return [{ json: { bodyJson, contactId: id } }];
